pub(crate) fn closed_slot_reports(
    checkpoint: &Path,
    directory: &Path,
    index: usize,
    entry: &plan::PlannedBenchmark,
) -> Result<std::collections::BTreeMap<usize, (PathBuf, serde_json::Value)>, Error> {
    checkpoint::completed::retained::reporting(checkpoint, directory, index, entry)
}

pub(crate) const MAX_SWEEP_BYTES: u64 = 16 * 1024 * 1024;
pub(crate) const MAX_CONFIGS: usize = 65536;

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct SweepFile {
    pub configs: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub repeat: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resources: Option<crate::planning::Resources>,
}

#[derive(Clone, Copy)]
pub(crate) struct Options<'a> {
    pub repeat: Option<u64>,
    pub max_steps: Option<u64>,
    pub track: Option<crate::cassette::Selector>,
    pub seed: Option<u64>,
    pub json: bool,
    pub show_output: bool,
    /// Suppress diagnostic evidence paths and detailed replay/recording information.
    pub quiet_output: bool,
    /// The process has both presentation streams attached to a terminal.
    ///
    /// Parallel configurations deliberately do not use a shared live line:
    /// their worker output is spooled independently and concurrent writes would
    /// make the terminal unreadable.
    pub interactive: bool,
    pub mode: Option<crate::tape::Mode>,
    pub tool_mode: Option<crate::tape::Mode>,
    pub tool_mode_explicit: bool,
    pub mcp_mode: Option<crate::tape::Mode>,
    pub respect_record_timings: bool,
    pub cassette_root: Option<&'a Path>,
    pub jobs: usize,
    pub max_active_attempts: Option<usize>,
    pub resume: bool,
    /// Maximum failed configurations tolerated while continuing. `None` keeps
    /// the existing fail-after-summary behaviour.
    pub continue_after_failures: Option<usize>,
    pub reconcile_completed: bool,
    pub import_grades: bool,
    pub recover_recording: bool,
    pub recover_continuation: bool,
}

impl Default for Options<'_> {
    fn default() -> Self {
        Self {
            repeat: None,
            max_steps: None,
            track: None,
            seed: None,
            json: false,
            show_output: false,
            quiet_output: false,
            interactive: false,
            mode: None,
            tool_mode: None,
            tool_mode_explicit: false,
            mcp_mode: None,
            respect_record_timings: false,
            cassette_root: None,
            jobs: 1,
            max_active_attempts: None,
            resume: false,
            continue_after_failures: None,
            reconcile_completed: false,
            import_grades: false,
            recover_recording: false,
            recover_continuation: false,
        }
    }
}

impl Options<'_> {
    fn live_progress(self) -> bool {
        self.interactive && !self.json && self.jobs == 1
    }
}

#[cfg(test)]
fn run(
    path: &str,
    json: bool,
    show_output: bool,
    mode: Option<crate::tape::Mode>,
    respect_record_timings: bool,
    cassette_root: Option<&Path>,
    output: &mut dyn Write,
) -> Result<(), Error> {
    run_with_options(
        path,
        Options {
            json,
            show_output,
            mode,
            respect_record_timings,
            cassette_root,
            ..Default::default()
        },
        output,
    )
}

/// Validate and execute every benchmark referenced by a sweep manifest.
pub(crate) fn run_with_options(
    path: &str,
    options: Options<'_>,
    output: &mut dyn Write,
) -> Result<(), Error> {
    if options.reconcile_completed && !options.resume {
        return Err(Error::Input(
            "--reconcile-completed requires --resume; original results were not replaced".into(),
        ));
    }
    let sweep_path = Path::new(path);
    let sweep = read_manifest(sweep_path)?;
    let options = Options {
        repeat: options.repeat.or(sweep.repeat),
        ..options
    };
    let Options { json, mode, .. } = options;
    let parent = sweep_path.parent().unwrap_or_else(|| Path::new("."));
    let stem = sweep_path
        .file_stem()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
        .unwrap_or("sweep");
    // Keep ownership through comparison, including moving older output trees.
    let _output_lock = lock::OutputLock::acquire(parent, stem)?;
    if options.recover_continuation {
        if !options.resume
            || mode.is_some()
            || options.import_grades
            || options.reconcile_completed
            || options.recover_recording
            || options.show_output
            || options.repeat.is_some()
            || options.max_steps.is_some()
            || options.track.is_some()
            || options.seed.is_some()
            || options.cassette_root.is_some()
            || options.respect_record_timings
            || options.max_active_attempts.is_some()
            || options.jobs != 1
        {
            return Err(Error::Input("--recover-continuation requires --resume and accepts no execution/selection options".into()));
        }
        let results = parent.join(format!("{stem}-results"));
        let saved = plan::SweepPlan::load(&results, parent, &sweep)?
            .ok_or_else(|| Error::Input("no retained sweep to recover".into()))?;
        if saved.execution.is_none() {
            return Err(Error::Input(
                "retained sweep is not a repeated campaign".into(),
            ));
        }
        let report = checkpoint::Inputs::recover_continuation(parent, &results, &saved)?;
        if options.json {
            writeln!(output, "{report}").map_err(crate::io_error)?;
        } else {
            writeln!(
                output,
                "Recovered continuation metadata: {} (no agents or evaluators started)",
                report["generation"].as_str().unwrap_or("unknown")
            )
            .map_err(crate::io_error)?;
        }
        return Ok(());
    }
    if options.recover_recording {
        if !options.resume
            || options.mode != Some(crate::tape::Mode::Record)
            || options.import_grades
            || options.reconcile_completed
            || options.show_output
            || options.repeat.is_some()
            || options.max_steps.is_some()
            || options.track.is_some()
            || options.seed.is_some()
            || options.cassette_root.is_some()
            || options.respect_record_timings
            || options.max_active_attempts.is_some()
        {
            return Err(Error::Input("--recover-recording requires --resume --record and accepts no execution/selection options".into()));
        }
        let results = parent.join(format!("{stem}-results"));
        let saved = plan::SweepPlan::load(&results, parent, &sweep)?
            .ok_or_else(|| Error::Input("no retained sweep to recover".into()))?;
        if saved.execution_mode != plan::SavedExecutionMode::Record || saved.execution.is_none() {
            return Err(Error::Input(
                "retained sweep is not a recording campaign".into(),
            ));
        }
        for report in checkpoint::Inputs::recover_recordings(parent, &results, &saved)? {
            if options.json {
                writeln!(output, "{report}").map_err(crate::io_error)?;
            } else {
                writeln!(
                    output,
                    "Recovered recording publication: {} (no agents or evaluators started)",
                    report["destination"].as_str().unwrap_or("unknown")
                )
                .map_err(crate::io_error)?;
            }
        }
        return Ok(());
    }
    if options.import_grades {
        if options.resume
            || options.reconcile_completed
            || options.show_output
            || mode.is_some()
            || options.respect_record_timings
            || options.cassette_root.is_some()
            || options.jobs != 1
            || options.max_active_attempts.is_some()
            || options.repeat.is_some()
            || options.max_steps.is_some()
            || options.track.is_some()
            || options.seed.is_some()
        {
            return Err(Error::Input(
                "--import-grades is report-only and cannot be combined with execution options"
                    .into(),
            ));
        }
        if plan::SweepPlan::source_snapshot(&parent.join(format!("{stem}-results")), parent)?
            .is_some_and(|saved| saved.execution.is_some())
        {
            return Err(Error::Input("campaign grade import requires saved-slot validation; existing results were not changed".into()));
        }
        return recovered::import(sweep_path, &sweep, parent, stem, json, output);
    }
    let prepared = phases::PreparedSweep::prepare(path, options, _output_lock, sweep, output)?;
    let activated = prepared.activate()?;
    let mut presentation = presentation::Presentation::new(output);
    activated
        .execute(&mut presentation)
        .finalize(&mut presentation)
}

fn cassette_filename(config: &BenchmarkConfig) -> String {
    format!(
        "benchmark-{}-{}-{}.jsonl",
        component(&config.agent),
        component(&config.workload),
        component(&config.model)
    )
}

/// Retain default replay inputs across fresh output attempts without copying
/// recording payloads or moving them out of history. Replay never writes these
/// files; a subsequent record gets a fresh results directory, not these links.
fn reuse_replay_inputs(
    source: &Path,
    destination: &Path,
    config: &BenchmarkConfig,
    allow_existing: bool,
) -> Result<(), Error> {
    let entries = match std::fs::read_dir(source) {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(error) => {
            return Err(Error::Io(format!(
                "cannot inspect preserved replay inputs {}: {error}",
                source.display()
            )));
        }
    };
    let filename = cassette_filename(config);
    let prefix = format!("{}-concurrency-", filename.trim_end_matches(".jsonl"));
    for (index, entry) in entries.enumerate() {
        if index >= MAX_CONFIGS {
            return Err(Error::Input("preserved replay input directory exceeds its entry bound; use an explicit --cassette-root".into()));
        }
        let entry = entry.map_err(|error| Error::Io(error.to_string()))?;
        let name = entry.file_name();
        let Some(text) = name.to_str() else {
            continue;
        };
        let replica = text
            .strip_prefix(&prefix)
            .and_then(|value| value.strip_suffix(".jsonl"))
            .and_then(|value| value.parse::<usize>().ok());
        if text != filename
            && !replica.is_some_and(|index| index > 0 && index <= config.concurrency)
        {
            continue;
        }
        let original = entry
            .path()
            .canonicalize()
            .map_err(|error| Error::Io(error.to_string()))?;
        std::fs::create_dir_all(destination).map_err(|error| Error::Io(error.to_string()))?;
        let target = destination.join(&name);
        if allow_existing && std::fs::symlink_metadata(&target).is_ok() {
            let metadata = std::fs::symlink_metadata(&target).map_err(crate::io_error)?;
            #[cfg(unix)]
            let same = {
                use std::os::unix::fs::MetadataExt;
                let source = std::fs::metadata(&original).map_err(crate::io_error)?;
                metadata.is_file()
                    && metadata.dev() == source.dev()
                    && metadata.ino() == source.ino()
            };
            #[cfg(not(unix))]
            let same =
                metadata.is_file() && target.canonicalize().ok() == original.canonicalize().ok();
            if same {
                continue;
            }
            return Err(Error::Input("existing replay input is not the preserved recording; restore its original hard link or use the original explicit --cassette-root".into()));
        }
        std::fs::hard_link(&original, destination.join(name)).map_err(|error| Error::Io(format!("cannot reuse preserved replay input {}: {error}; use an explicit --cassette-root to replay directly from its preserved location", original.display())))?;
    }
    Ok(())
}

fn write_progress(
    output: &mut dyn Write,
    index: usize,
    total: usize,
    config_path: &Path,
    config: &BenchmarkConfig,
) -> Result<(), Error> {
    let name = config_path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("benchmark");
    // A manifest or model identifier may contain terminal control characters;
    // keep this human-facing status to exactly one safe line.
    let one_line = |value: &str| {
        value
            .chars()
            .map(|ch| if ch.is_control() { ' ' } else { ch })
            .collect::<String>()
    };
    writeln!(
        output,
        "Starting benchmark ({}/{}; {}% reached): {} — {}, {}, {}, {}, trial {} (concurrency {})",
        index + 1,
        total,
        (index + 1) * 100 / total,
        one_line(name),
        one_line(&config.agent),
        one_line(&config.provider),
        one_line(&config.model),
        one_line(&config.workload),
        one_line(config.trial.as_deref().unwrap_or("default")),
        config.concurrency,
    )
    .and_then(|_| output.flush())
    .map_err(|error| Error::Io(format!("cannot write sweep progress: {error}")))
}

fn add_failure(failures: &mut Vec<(String, Vec<String>)>, config: String, message: String) {
    if let Some((_, configs)) = failures.iter_mut().find(|(item, _)| *item == message) {
        configs.push(config);
    } else {
        failures.push((message, vec![config]));
    }
}

/// Shared bounded format for setup, execution and offline comparison. A full
/// dataset/agent matrix must not silently hit a prompt-sized file limit.
pub(crate) fn read_manifest(path: &Path) -> Result<SweepFile, Error> {
    let text = read_manifest_text(path)?;
    let label = path.display().to_string();
    let value: toml::Value = toml::from_str(&text)
        .map_err(|error| Error::Input(format!("cannot parse sweep {label}: {error}")))?;
    parse_manifest(path, value)
}

pub(crate) fn read_manifest_text(path: &Path) -> Result<String, Error> {
    let file = std::fs::File::open(path)
        .map_err(|error| Error::Input(format!("cannot read TOML {}: {error}", path.display())))?;
    let mut text = String::new();
    file.take(MAX_SWEEP_BYTES + 1)
        .read_to_string(&mut text)
        .map_err(|error| Error::Input(format!("cannot read TOML {}: {error}", path.display())))?;
    if text.len() as u64 > MAX_SWEEP_BYTES {
        return Err(Error::Input(format!(
            "TOML {} exceeds 16 MiB",
            path.display()
        )));
    }
    Ok(text)
}

/// Validate an already captured TOML snapshot without rereading its path.
pub(crate) fn parse_manifest(path: &Path, value: toml::Value) -> Result<SweepFile, Error> {
    let label = path.display().to_string();
    if !value
        .as_table()
        .is_some_and(|table| table.contains_key("configs"))
    {
        return Err(Error::Input(format!(
            "{label} is not a sweep TOML; expected `configs = [...]` (a normal benchmark TOML was supplied)"
        )));
    }
    let sweep: SweepFile = value
        .try_into()
        .map_err(|error| Error::Input(format!("invalid sweep {label}: {error}")))?;
    if sweep.configs.is_empty() {
        return Err(Error::Input(format!(
            "sweep {label} contains no benchmark configurations"
        )));
    }
    if sweep.configs.len() > MAX_CONFIGS {
        return Err(Error::Input(format!(
            "sweep {label} contains {} configurations; the maximum is {MAX_CONFIGS}",
            sweep.configs.len()
        )));
    }
    let parent = path.parent().unwrap_or_else(|| Path::new("."));
    for reference in &sweep.configs {
        checked_benchmark_reference(parent, reference, &label)?;
    }
    Ok(sweep)
}

fn isolated_config(config: &BenchmarkConfig, result_dir: &Path) -> BenchmarkConfig {
    let mut isolated = config.clone();
    isolated.workspace = result_dir.join("workspace").to_string_lossy().into_owned();
    isolated.log_file = result_dir.join("run.log").to_string_lossy().into_owned();
    if let Some(measurements) = isolated.measurements.as_mut() {
        measurements.directory = result_dir
            .join("measurements")
            .to_string_lossy()
            .into_owned();
    }
    isolated
}

#[cfg(all(test, unix))]
#[path = "../tests/unit/sweep_boundaries.rs"]
mod boundary_tests;

#[cfg(test)]
mod tests {
    use super::{Options, run, write_progress};
    use std::io::Write;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn temp_file(name: &str, contents: &str) -> std::path::PathBuf {
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let directory = std::env::temp_dir().join(format!("asb-sweep-{stamp}"));
        std::fs::create_dir_all(&directory).expect("directory");
        let path = directory.join(name);
        std::fs::write(&path, contents).expect("file");
        path
    }

    #[test]
    fn manifest_supports_complete_original_populations_and_multi_agent_matrices() {
        for count in [300, 500, 2294, (2294 + 300 + 500 + 80 + 89) * 8] {
            let reference = "original-instance-selection-agent-provider-model-configuration.toml";
            let configs = vec![reference.to_owned(); count];
            let text = toml::to_string(&super::SweepFile {
                resources: None,
                configs,
                repeat: None,
            })
            .unwrap();
            if count >= 2294 {
                assert!(text.len() > 64 * 1024);
            }
            let path = temp_file("population.toml", &text);
            std::fs::write(path.parent().unwrap().join(reference), "fixture").unwrap();
            assert_eq!(super::read_manifest(&path).unwrap().configs.len(), count);
            std::fs::remove_dir_all(path.parent().unwrap()).unwrap();
        }
    }

    #[test]
    fn oversized_manifest_bytes_and_entry_counts_are_rejected_before_execution() {
        let path = temp_file(
            "large.toml",
            &"x".repeat(super::MAX_SWEEP_BYTES as usize + 1),
        );
        assert!(
            super::read_manifest(&path)
                .unwrap_err()
                .to_string()
                .contains("16 MiB")
        );
        let configs = vec!["benchmark.toml".to_owned(); super::MAX_CONFIGS + 1];
        std::fs::write(
            &path,
            toml::to_string(&super::SweepFile {
                resources: None,
                configs,
                repeat: None,
            })
            .unwrap(),
        )
        .unwrap();
        assert!(
            super::read_manifest(&path)
                .unwrap_err()
                .to_string()
                .contains("maximum is 65536")
        );
        std::fs::remove_dir_all(path.parent().unwrap()).unwrap();
    }

    #[test]
    fn missing_later_references_do_not_begin_a_partial_sweep() {
        let path = temp_file("sweep.toml", "configs=['present.toml','missing.toml']\n");
        std::fs::write(
            path.parent().unwrap().join("present.toml"),
            "agent='not-installed'\nworkload='bug-fix'\nprovider='local'\nmodel='fixture'\n",
        )
        .unwrap();
        let error = run(
            path.to_str().unwrap(),
            false,
            false,
            None,
            false,
            None,
            &mut Vec::new(),
        )
        .unwrap_err();
        assert!(error.to_string().contains("missing benchmark"));
        assert!(!path.parent().unwrap().join("sweep-results").exists());
        std::fs::remove_dir_all(path.parent().unwrap()).unwrap();
    }

    #[test]
    fn progress_is_flushed_and_keeps_untrusted_labels_to_one_line() {
        #[derive(Default)]
        struct Capture {
            bytes: Vec<u8>,
            flushed: bool,
        }
        impl Write for Capture {
            fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
                self.bytes.extend_from_slice(bytes);
                Ok(bytes.len())
            }
            fn flush(&mut self) -> std::io::Result<()> {
                self.flushed = true;
                Ok(())
            }
        }
        let mut config: crate::benchmark::BenchmarkConfig =
            toml::from_str("agent='pi'\nworkload='bug-fix'\nprovider='local'\nmodel='model'\n")
                .unwrap();
        config.model = "model\n\u{1b}[31m".into();
        let mut capture = Capture::default();
        write_progress(
            &mut capture,
            1,
            3,
            std::path::Path::new("bad\nname.toml"),
            &config,
        )
        .unwrap();
        let text = String::from_utf8(capture.bytes).unwrap();
        assert!(capture.flushed);
        assert!(text.contains("(2/3; 66% reached): bad name.toml"));
        assert!(text.contains("trial default (concurrency 1)"));
        assert_eq!(text.lines().count(), 1);
        assert!(!text.contains('\u{1b}'));
    }

    #[test]
    fn progress_output_failures_are_reported() {
        struct Broken;
        impl Write for Broken {
            fn write(&mut self, _: &[u8]) -> std::io::Result<usize> {
                Err(std::io::Error::new(
                    std::io::ErrorKind::BrokenPipe,
                    "closed",
                ))
            }
            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }
        let config: crate::benchmark::BenchmarkConfig =
            toml::from_str("agent='pi'\nworkload='bug-fix'\nprovider='local'\nmodel='model'\n")
                .unwrap();
        let error = write_progress(
            &mut Broken,
            0,
            1,
            std::path::Path::new("test.toml"),
            &config,
        )
        .unwrap_err();
        assert!(error.to_string().contains("cannot write sweep progress"));
    }

    #[test]
    fn live_progress_requires_an_interactive_serial_human_sweep() {
        assert!(
            Options {
                interactive: true,
                ..Default::default()
            }
            .live_progress()
        );
        assert!(
            !Options {
                interactive: false,
                ..Default::default()
            }
            .live_progress()
        );
        assert!(
            !Options {
                interactive: true,
                json: true,
                ..Default::default()
            }
            .live_progress()
        );
        assert!(
            !Options {
                interactive: true,
                jobs: 2,
                ..Default::default()
            }
            .live_progress()
        );
    }

    #[test]
    fn rejects_a_normal_benchmark_as_a_sweep() {
        let path = temp_file(
            "benchmark.toml",
            "agent = \"codex\"\nworkload = \"bug-fix\"\nprovider = \"openrouter\"\nmodel = \"tool-model\"\n",
        );
        let error = run(
            path.to_str().expect("path"),
            false,
            false,
            None,
            false,
            None,
            &mut Vec::new(),
        )
        .expect_err("normal benchmark must be rejected");
        assert!(error.to_string().contains("not a sweep TOML"));
    }

    #[test]
    fn rejects_unsafe_references_before_execution() {
        let path = temp_file("sweep.toml", "configs = [\"../benchmark.toml\"]\n");
        let error = run(
            path.to_str().expect("path"),
            false,
            false,
            None,
            false,
            None,
            &mut Vec::new(),
        )
        .expect_err("parent traversal must be rejected");
        assert!(error.to_string().contains("unsafe benchmark path"));
    }

    #[test]
    fn regenerates_comparison_after_a_partial_sweep() {
        let _disk = crate::disk_space::test_available_mib(100_000);
        let path = temp_file("sweep.toml", "configs = [\"benchmark.toml\"]\n");
        let root = path.parent().unwrap();
        std::fs::create_dir(root.join(".asb")).unwrap();
        std::fs::write(
            root.join(".asb/project.toml"),
            toml::to_string(&crate::project::ProjectConfig::default()).unwrap(),
        )
        .unwrap();
        let benchmark = path.parent().expect("sweep parent").join("benchmark.toml");
        std::fs::write(
            &benchmark,
            "agent = \"not-installed\"\nworkload = \"bug-fix\"\nprovider = \"local\"\nmodel = \"test-model\"\n",
        )
        .expect("benchmark");
        let error = run(
            path.to_str().expect("path"),
            false,
            false,
            None,
            false,
            None,
            &mut Vec::new(),
        )
        .expect_err("invalid agent leaves a failed sweep");
        assert!(error.to_string().contains("failed benchmark"));
        let report = path
            .parent()
            .expect("parent")
            .join("results/sweep-comparison/report.html");
        assert!(report.is_file(), "automatic comparison report exists");
        assert_eq!(
            std::fs::read_dir(root.join(".asb/execution-plans"))
                .unwrap()
                .count(),
            1,
            "failed execution must retain policy evidence only in its isolated project"
        );
    }
}
